import math
import torch
import torch.nn as nn
import torch.nn.init as init
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.extern .shared .align 4 .b8 smem[];
.visible .entry conv2d_forward(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 pN,
    .param .u32 pCin,
    .param .u32 pCout,
    .param .u32 pH,
    .param .u32 pW,
    .param .u32 pHout,
    .param .u32 pWout,
    .param .u32 pKh,
    .param .u32 pKw,
    .param .u32 pSh,
    .param .u32 pSw,
    .param .u32 pPh,
    .param .u32 pPw,
    .param .u32 pDh,
    .param .u32 pDw,
    .param .u32 pGroups,
    .param .u32 pCinPG,
    .param .u32 pCoutPG,
    .param .u32 pHasBias
)
{
    .reg .pred %p<22>;
    .reg .pred %pNA, %pOOB;
    .reg .b32 %r<160>;
    .reg .b64 %rd<80>;
    .reg .f32 %f<8>;
    // Explicitly declare named registers used below
    // 32-bit scalar params
    .reg .b32 %rN, %rCin, %rCout, %rH, %rW, %rHout, %rWout;
    .reg .b32 %rKh, %rKw, %rSh, %rSw, %rPh, %rPw, %rDh, %rDw;
    .reg .b32 %rGroups, %rCinPG, %rCoutPG, %rHasBias;
    // Thread/block indices
    .reg .b32 %rTx, %rTy, %rTz, %rBx, %rBy, %rBz, %rBDx, %rBDy, %rBDz;
    // Logical indices and temporaries
    .reg .b32 %rOw, %rOh, %rNOC, %rTot, %rNidx, %rOc, %rG, %rInBase;
    .reg .b32 %rInCh;
    // Signed/unsigned views and arithmetic temps
    .reg .b32 %rOh_s, %rOw_s, %rPh_s, %rPw_s, %rSh_s, %rSw_s, %rDh_s, %rDw_s, %rH_s, %rW_s;
    .reg .b32 %rIcg, %rKhIter, %rTmp1, %rTmp2, %rIh_s;
    .reg .b32 %rKwIter, %rTmp3, %rTmp4, %rIw_s;
    .reg .b32 %rTmp5, %rTmp6;
    .reg .b32 %rA, %rIh_u, %rIw_u, %rB, %rInIdx;
    .reg .b32 %rC, %rD, %rWIdx, %rY1, %rY2, %rYIdx;
    // Tiling registers
    .reg .b32 %rOhBase, %rOwBase, %rOhEnd, %rOwEnd, %rHoutm1, %rWoutm1, %rBDyMinus1, %rBDxMinus1, %rKhMinus1, %rKwMinus1;
    .reg .b32 %rOhBase_s, %rOwBase_s, %rOhEnd_s;
    .reg .b32 %rIhMin_s, %rIhMax_s, %rIwMin_s, %rIwMax_s, %rThAct, %rTwAct, %rTwm, %rTotal, %rGTid, %rCTA, %rIdx, %rTileH, %rTileW;
    .reg .b32 %rIhTileOff_s, %rIwTileOff_s, %rIhTileOff_u, %rIwTileOff_u, %rSmemElemOff;
    // Weight staging registers
    .reg .b32 %rTotalW, %rIdxW, %rKhW, %rKwW, %rInTileElems, %rWZBase, %rSmWIdx;
    // 64-bit pointers/offsets
    .reg .b64 %rdInOff, %rdInPtr, %rdWOff, %rdWPtr, %rdBOff, %rdBPtr, %rdYOff, %rdYPtr;
    .reg .b64 %rdSmBase, %rdSmOff, %rdSmWBase, %rdSmWOff, %rdSmWPtr;
    // Load pointers
    ld.param.u64 %rd1, [x_ptr];
    ld.param.u64 %rd2, [w_ptr];
    ld.param.u64 %rd3, [b_ptr];
    ld.param.u64 %rd4, [y_ptr];
    // Load scalars
    ld.param.u32 %rN, [pN];
    ld.param.u32 %rCin, [pCin];
    ld.param.u32 %rCout, [pCout];
    ld.param.u32 %rH, [pH];
    ld.param.u32 %rW, [pW];
    ld.param.u32 %rHout, [pHout];
    ld.param.u32 %rWout, [pWout];
    ld.param.u32 %rKh, [pKh];
    ld.param.u32 %rKw, [pKw];
    ld.param.u32 %rSh, [pSh];
    ld.param.u32 %rSw, [pSw];
    ld.param.u32 %rPh, [pPh];
    ld.param.u32 %rPw, [pPw];
    ld.param.u32 %rDh, [pDh];
    ld.param.u32 %rDw, [pDw];
    ld.param.u32 %rGroups, [pGroups];
    ld.param.u32 %rCinPG, [pCinPG];
    ld.param.u32 %rCoutPG, [pCoutPG];
    ld.param.u32 %rHasBias, [pHasBias];
    // Thread/block indices
    mov.u32 %rTx, %tid.x;
    mov.u32 %rTy, %tid.y;
    mov.u32 %rTz, %tid.z;
    mov.u32 %rBx, %ctaid.x;
    mov.u32 %rBy, %ctaid.y;
    mov.u32 %rBz, %ctaid.z;
    mov.u32 %rBDx, %ntid.x;
    mov.u32 %rBDy, %ntid.y;
    mov.u32 %rBDz, %ntid.z;
    // Compute logical indices
    mad.lo.u32 %rOw, %rBx, %rBDx, %rTx;
    mad.lo.u32 %rOh, %rBy, %rBDy, %rTy;
    mad.lo.u32 %rNOC, %rBz, %rBDz, %rTz;
    // total elements along N*Cout
    mul.lo.u32 %rTot, %rN, %rCout;
    // n and oc decomposition
    div.u32 %rNidx, %rNOC, %rCout;
    rem.u32 %rOc,   %rNOC, %rCout;
    // group and input-channel base within group
    div.u32 %rG, %rOc, %rCoutPG;       // g = oc / cout_pg
    mul.lo.u32 %rInBase, %rG, %rCinPG; // in_ch_base = g * cin_pg
    // Convert scalars to s32 where needed
    cvt.s32.u32 %rOh_s, %rOh;
    cvt.s32.u32 %rOw_s, %rOw;
    cvt.s32.u32 %rPh_s, %rPh;
    cvt.s32.u32 %rPw_s, %rPw;
    cvt.s32.u32 %rSh_s, %rSh;
    cvt.s32.u32 %rSw_s, %rSw;
    cvt.s32.u32 %rDh_s, %rDh;
    cvt.s32.u32 %rDw_s, %rDw;
    cvt.s32.u32 %rH_s, %rH;
    cvt.s32.u32 %rW_s, %rW;
    // Compute block tile bases and extents
    // oh_base = by*BDy; ow_base = bx*BDx
    mul.lo.u32 %rOhBase, %rBy, %rBDy;
    mul.lo.u32 %rOwBase, %rBx, %rBDx;
    // oh_end = min(oh_base + BDy - 1, Hout - 1);
    sub.u32 %rBDyMinus1, %rBDy, 1;
    add.u32 %rTmp1, %rOhBase, %rBDyMinus1;
    sub.u32 %rHoutm1, %rHout, 1;
    min.u32 %rOhEnd, %rTmp1, %rHoutm1;
    // ow_end = min(ow_base + BDx - 1, Wout - 1);
    sub.u32 %rBDxMinus1, %rBDx, 1;
    add.u32 %rTmp2, %rOwBase, %rBDxMinus1;
    sub.u32 %rWoutm1, %rWout, 1;
    min.u32 %rOwEnd, %rTmp2, %rWoutm1;
    // Convert bases/ends to s32
    cvt.s32.u32 %rOhBase_s, %rOhBase;
    cvt.s32.u32 %rOwBase_s, %rOwBase;
    cvt.s32.u32 %rOhEnd_s,  %rOhEnd;
    // ih_min = oh_base*Sh - Ph
    mul.lo.s32 %rTmp1, %rOhBase_s, %rSh_s;
    sub.s32    %rIhMin_s, %rTmp1, %rPh_s;
    // ih_max = oh_end*Sh - Ph + (Kh-1)*Dh
    mul.lo.s32 %rTmp2, %rOhEnd_s, %rSh_s;
    sub.s32    %rTmp2, %rTmp2, %rPh_s;
    sub.u32    %rKhMinus1, %rKh, 1;
    cvt.s32.u32 %rTmp3, %rKhMinus1;
    mul.lo.s32 %rTmp3, %rTmp3, %rDh_s;
    add.s32    %rIhMax_s, %rTmp2, %rTmp3;
    // iw_min = ow_base*Sw - Pw
    mul.lo.s32 %rTmp4, %rOwBase_s, %rSw_s;
    sub.s32    %rIwMin_s, %rTmp4, %rPw_s;
    // iw_max = ow_end*Sw - Pw + (Kw-1)*Dw
    cvt.s32.u32 %rTmp5, %rOwEnd;
    mul.lo.s32 %rTmp5, %rTmp5, %rSw_s;
    sub.s32    %rTmp5, %rTmp5, %rPw_s;
    sub.u32    %rKwMinus1, %rKw, 1;
    cvt.s32.u32 %rTmp6, %rKwMinus1;
    mul.lo.s32 %rTmp6, %rTmp6, %rDw_s;
    add.s32    %rIwMax_s, %rTmp5, %rTmp6;
    // Active tile sizes
    sub.s32 %rTmp1, %rIhMax_s, %rIhMin_s;
    add.s32 %rThAct, %rTmp1, 1;
    sub.s32 %rTmp2, %rIwMax_s, %rIwMin_s;
    add.s32 %rTwAct, %rTmp2, 1;
    // Twm = (BDx-1)*Sw + (Kw-1)*Dw + 1
    cvt.s32.u32 %rTmp3, %rBDxMinus1;
    mul.lo.s32 %rTmp3, %rTmp3, %rSw_s;
    cvt.s32.u32 %rTmp4, %rKwMinus1;
    mul.lo.s32 %rTmp4, %rTmp4, %rDw_s;
    add.s32    %rTmp3, %rTmp3, %rTmp4;
    add.s32    %rTmp3, %rTmp3, 1;
    cvt.u32.s32 %rTwm, %rTmp3;
    // Compute weight shared-memory base offset after input tile region
    cvt.u32.s32 %rInTileElems, %rThAct;
    mul.lo.u32 %rInTileElems, %rInTileElems, %rTwm;
    mov.f32 %f0, 0f00000000;
    mov.u64 %rdSmBase, smem;
    mul.wide.u32 %rdSmWOff, %rInTileElems, 4;
    add.u64 %rdSmWBase, %rdSmBase, %rdSmWOff;
    // CTA and thread linear indices for cooperative load
    mul.lo.u32 %rCTA, %rBDx, %rBDy;
    mad.lo.u32 %rGTid, %rTy, %rBDx, %rTx;
    // Precompute not-active predicate: pNA = (ow>=Wout) || (oh>=Hout) || (NOC>=Tot)
    setp.ge.u32 %p0, %rOw, %rWout;
    setp.ge.u32 %p1, %rOh, %rHout;
    setp.ge.u32 %p2, %rNOC, %rTot;
    or.pred %p3, %p0, %p1;
    or.pred %pNA, %p3, %p2;
    // icg loop
    mov.u32 %rIcg, 0;
ICG_LOOP:
    setp.ge.u32 %p4, %rIcg, %rCinPG;
    @%p4 bra ICG_END;
    add.u32 %rInCh, %rInBase, %rIcg;
    // Cooperative load input tile for this icg into shared memory
    // total elements = ThAct * TwAct
    cvt.u32.s32 %rTmp1, %rThAct;
    cvt.u32.s32 %rTmp2, %rTwAct;
    mul.lo.u32 %rTotal, %rTmp1, %rTmp2;
    mov.u32 %rIdx, %rGTid;
SMEM_LOAD_LOOP:
    setp.ge.u32 %p5, %rIdx, %rTotal;
    @%p5 bra SMEM_LOAD_DONE;
    // th = idx / TwAct; tw = idx % TwAct
    div.u32 %rTileH, %rIdx, %rTmp2;
    rem.u32 %rTileW, %rIdx, %rTmp2;
    // ih = ih_min + th; iw = iw_min + tw
    cvt.s32.u32 %rTmp3, %rTileH;
    add.s32 %rTmp3, %rIhMin_s, %rTmp3;
    cvt.s32.u32 %rTmp4, %rTileW;
    add.s32 %rTmp4, %rIwMin_s, %rTmp4;
    // bounds check input
    setp.lt.s32 %p6, %rTmp3, 0;
    setp.ge.s32 %p7, %rTmp3, %rH_s;
    or.pred %p8, %p6, %p7;
    setp.lt.s32 %p9, %rTmp4, 0;
    setp.ge.s32 %p10, %rTmp4, %rW_s;
    or.pred %p11, %p9, %p10;
    or.pred %pOOB, %p8, %p11;
    @%pOOB bra SMEM_STORE_ZERO;
    // Compute input index and load
    mad.lo.u32 %rA, %rNidx, %rCin, %rInCh;
    cvt.u32.s32 %rIh_u, %rTmp3;
    cvt.u32.s32 %rIw_u, %rTmp4;
    mad.lo.u32 %rB, %rA, %rH, %rIh_u;
    mad.lo.u32 %rInIdx, %rB, %rW, %rIw_u;
    mul.wide.u32 %rdInOff, %rInIdx, 4;
    add.u64 %rdInPtr, %rd1, %rdInOff;
    // Compute smem address and issue async copy for in-bounds
    // smem offset = (th*Twm + tw) * 4
    mul.lo.u32 %rSmemElemOff, %rTileH, %rTwm;
    add.u32 %rSmemElemOff, %rSmemElemOff, %rTileW;
    mul.wide.u32 %rdSmOff, %rSmemElemOff, 4;
    add.u64 %rdSmOff, %rdSmBase, %rdSmOff;
    cp.async.ca.shared.global [%rdSmOff], [%rdInPtr], 4;
    bra SMEM_NEXT;
SMEM_STORE_ZERO:
    // compute smem offset for zero-fill
    mul.lo.u32 %rSmemElemOff, %rTileH, %rTwm;
    add.u32 %rSmemElemOff, %rSmemElemOff, %rTileW;
    mul.wide.u32 %rdSmOff, %rSmemElemOff, 4;
    add.u64 %rdSmOff, %rdSmBase, %rdSmOff;
    mov.f32 %f1, 0f00000000;
    st.shared.f32 [%rdSmOff], %f1;
SMEM_NEXT:
    // next
    add.u32 %rIdx, %rIdx, %rCTA;
    bra SMEM_LOAD_LOOP;
SMEM_LOAD_DONE:
    // finalize async copies
    cp.async.commit_group;
    cp.async.wait_group 0;
    // Cooperative load weights for this icg and oc into shared memory region after input tile
    mul.lo.u32 %rTotalW, %rKh, %rKw;
    mov.u32 %rIdxW, %rGTid;
    // per-OC shared-memory base offset (in elements) for weights: tz * (Kh*Kw)
    mul.lo.u32 %rWZBase, %rTz, %rTotalW;
W_SMEM_LOAD_LOOP:
    setp.ge.u32 %p19, %rIdxW, %rTotalW;
    @%p19 bra W_SMEM_LOAD_DONE;
    // kh = idxW / Kw; kw = idxW % Kw
    div.u32 %rKhW, %rIdxW, %rKw;
    rem.u32 %rKwW, %rIdxW, %rKw;
    // Compute weight index: ((((oc*CinPG) + icg)*Kh + kh)*Kw + kw)
    mad.lo.u32 %rC, %rOc, %rCinPG, %rIcg;
    mad.lo.u32 %rD, %rC, %rKh, %rKhW;
    mad.lo.u32 %rWIdx, %rD, %rKw, %rKwW;
    mul.wide.u32 %rdWOff, %rWIdx, 4;
    add.u64 %rdWPtr, %rd2, %rdWOff;
    ld.global.f32 %f4, [%rdWPtr];
    // store to shared weights buffer at linear index (tz*TotalW + idxW)
    add.u32 %rSmWIdx, %rIdxW, %rWZBase;
    mul.wide.u32 %rdSmWOff, %rSmWIdx, 4;
    add.u64 %rdSmWPtr, %rdSmWBase, %rdSmWOff;
    st.shared.f32 [%rdSmWPtr], %f4;
    add.u32 %rIdxW, %rIdxW, %rCTA;
    bra W_SMEM_LOAD_LOOP;
W_SMEM_LOAD_DONE:
    // synchronize before compute
    bar.sync 0;
    // If thread not active, skip compute but continue to next icg
    @%pNA bra ICG_CONTINUE;
    // kh loop
    mov.u32 %rKhIter, 0;
KH_LOOP:
    setp.ge.u32 %p12, %rKhIter, %rKh;
    @%p12 bra KH_END;
    // ih = oh*Sh - Ph + kh*Dh
    mul.lo.s32 %rTmp1, %rOh_s, %rSh_s;
    mul.lo.s32 %rTmp2, %rKhIter, %rDh_s;
    add.s32    %rIh_s, %rTmp1, %rTmp2;
    sub.s32    %rIh_s, %rIh_s, %rPh_s;
    // if ih out of bounds, skip kw loop
    setp.lt.s32 %p13, %rIh_s, 0;
    @%p13 bra KH_CONT;
    setp.ge.s32 %p14, %rIh_s, %rH_s;
    @%p14 bra KH_CONT;
    // kw loop
    mov.u32 %rKwIter, 0;
KW_LOOP:
    setp.ge.u32 %p15, %rKwIter, %rKw;
    @%p15 bra KW_END;
    // iw = ow*Sw - Pw + kw*Dw
    mul.lo.s32 %rTmp3, %rOw_s, %rSw_s;
    mul.lo.s32 %rTmp4, %rKwIter, %rDw_s;
    add.s32    %rIw_s, %rTmp3, %rTmp4;
    sub.s32    %rIw_s, %rIw_s, %rPw_s;
    // if iw out of bounds, continue
    setp.lt.s32 %p16, %rIw_s, 0;
    @%p16 bra KW_CONT;
    setp.ge.s32 %p17, %rIw_s, %rW_s;
    @%p17 bra KW_CONT;
    // Load from shared memory: offsets based on tile origin (ih_min, iw_min)
    sub.s32 %rIhTileOff_s, %rIh_s, %rIhMin_s;
    sub.s32 %rIwTileOff_s, %rIw_s, %rIwMin_s;
    cvt.u32.s32 %rIhTileOff_u, %rIhTileOff_s;
    cvt.u32.s32 %rIwTileOff_u, %rIwTileOff_s;
    mul.lo.u32 %rSmemElemOff, %rIhTileOff_u, %rTwm;
    add.u32 %rSmemElemOff, %rSmemElemOff, %rIwTileOff_u;
    mul.wide.u32 %rdSmOff, %rSmemElemOff, 4;
    add.u64 %rdSmOff, %rdSmBase, %rdSmOff;
    ld.shared.f32 %f1, [%rdSmOff];
    // Load weight from shared memory: idxW = kh*Kw + kw
    mad.lo.u32 %rWIdx, %rKhIter, %rKw, %rKwIter;
    add.u32 %rWIdx, %rWIdx, %rWZBase;
    mul.wide.u32 %rdSmWOff, %rWIdx, 4;
    add.u64 %rdSmWPtr, %rdSmWBase, %rdSmWOff;
    ld.shared.f32 %f2, [%rdSmWPtr];
    // acc += x * w
    fma.rn.f32 %f0, %f1, %f2, %f0;
KW_CONT:
    add.u32 %rKwIter, %rKwIter, 1;
    bra KW_LOOP;
KW_END:
KH_CONT:
    add.u32 %rKhIter, %rKhIter, 1;
    bra KH_LOOP;
KH_END:
ICG_CONTINUE:
    bar.sync 0;
    add.u32 %rIcg, %rIcg, 1;
    bra ICG_LOOP;
ICG_END:
    // If thread not active, skip bias and store
    @%pNA bra EXIT;
    // Add bias if present
    setp.eq.u32 %p18, %rHasBias, 0;
    @%p18 bra NO_BIAS;
    mul.wide.u32 %rdBOff, %rOc, 4;
    add.u64 %rdBPtr, %rd3, %rdBOff;
    ld.global.f32 %f3, [%rdBPtr];
    add.f32 %f0, %f0, %f3;
NO_BIAS:
    // Store output: (((n*Cout + oc)*Hout + oh)*Wout + ow)
    mad.lo.u32 %rY1, %rNidx, %rCout, %rOc;
    mad.lo.u32 %rY2, %rY1, %rHout, %rOh;
    mad.lo.u32 %rYIdx, %rY2, %rWout, %rOw;
    mul.wide.u32 %rdYOff, %rYIdx, 4;
    add.u64 %rdYPtr, %rd4, %rdYOff;
    st.global.f32 [%rdYPtr], %f0;
EXIT:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_forward")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        if isinstance(kernel_size, tuple):
            assert kernel_size[0] == kernel_size[1], "Only square kernels supported"
            k = int(kernel_size[0])
        else:
            k = int(kernel_size)
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = k
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)
        assert self.in_channels % self.groups == 0, "in_channels must be divisible by groups"
        assert self.out_channels % self.groups == 0, "out_channels must be divisible by groups"

        # Parameters shape match torch.nn.Conv2d
        weight = torch.empty(self.out_channels, self.in_channels // self.groups, k, k)
        init.kaiming_uniform_(weight, a=math.sqrt(5))
        self.weight = nn.Parameter(weight)

        if bias:
            fan_in = (self.in_channels // self.groups) * k * k
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            b = torch.empty(self.out_channels)
            init.uniform_(b, -bound, bound)
            self.bias = nn.Parameter(b)
        else:
            self.register_parameter("bias", None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "Only float32 tensors are supported"
        N, Cin, H, W = x.shape
        assert Cin == self.in_channels, "Input channels mismatch"
        k = self.kernel_size
        sh = self.stride
        sw = self.stride
        ph = self.padding
        pw = self.padding
        dh = self.dilation
        dw = self.dilation
        groups = self.groups

        # Output dimensions
        Hout = (H + 2 * ph - dh * (k - 1) - 1) // sh + 1
        Wout = (W + 2 * pw - dw * (k - 1) - 1) // sw + 1

        y = torch.empty((N, self.out_channels, Hout, Wout), device=x.device, dtype=x.dtype)

        cin_pg = self.in_channels // groups
        cout_pg = self.out_channels // groups
