    cvt.s32.u32 %rPh_s, %rPh;
    cvt.s32.u32 %rPw_s, %rPw;
    cvt.s32.u32 %rSh_s, %rSh;
    cvt.s32.u32 %rSw_s, %rSw;
    cvt.s32.u32 %rDh_s, %rDh;
