    // smem offset = (th*Twm + tw) * 4
    mul.lo.u32 %rSmemElemOff, %rTileH, %rTwm;
    add.u32 %rSmemElemOff, %rSmemElemOff, %rTileW;
    mul.wide.u32 %rdSmOff, %rSmemElemOff, 4;
    add.u64 %rdSmOff, %rdSmBase, %rdSmOff;
    cp.async.ca.shared.global [%rdSmOff], [%rdInPtr], 4;
    bra SMEM_NEXT;
